-- Restore students' original usernames.
--
-- WHY
-- student_platform used to authenticate against old gennis, where a student's
-- username was their own (e.g. "afruz_web"). v2's logins came from
-- seed_student_users.py, which never read gennis_student.username — it used the
-- phone number or fell back to s<gennis_id>, so "afruz_web" became "s13807".
-- When student_platform was repointed at the v2 shim, every student's known login
-- silently stopped working. This puts the original names back.
--
-- PASSWORDS ARE NOT TOUCHED. They are already "12345678" for every student:
-- seed_student_users.py hardcoded that hash and reset_all_passwords.py
-- (DEFAULT_PASSWORD = "12345678") later reset every non-deleted account to it.
-- Verified on a 300-row sample — 300 of 300 hashes verify. There is nothing to change.
--
-- COLLISIONS
-- The originals are not unique — 18 students are called "madina", 16 "sevinch" —
-- and UNIQUE(username) is shared with teachers, staff and parents. Resolution was
-- computed once and frozen into the list below:
--   * the first claimant keeps the name, ordered by user id so the result is stable
--   * later claimants take a numeric suffix: DOSTON, DOSTON2, DOSTON3 ...
--   * a name held by an account NOT being renamed is never taken
-- 15888 students are renamed, 2881 of them via a suffix. None were left
-- unplaceable.
--
-- NOTE: 4788 of these names contain spaces (e.g. "OQBO'TAYEV TOXIR"). They are
-- restored exactly as they were — the job here is fidelity to what students already
-- know, not tidying. Worth a separate decision if spaces cause trouble at login.
--
-- Re-runnable: the UPDATE only fires where the name actually differs, and refuses
-- any target already held by another account.
--
-- Usage:  psql -v apply=0   -- dry run (DEFAULT)
--         psql -v apply=1   -- write

\if :{?apply} \else \set apply 0 \endif

BEGIN;

CREATE TEMP TABLE want (user_id bigint PRIMARY KEY, new_username text) ON COMMIT DROP;
