CREATE TEMP TABLE plan ON COMMIT DROP AS
SELECT w.user_id, u.username AS current_username, w.new_username
FROM want w
JOIN "user" u ON u.id = w.user_id
WHERE u.role = 'student'
  AND u.username IS DISTINCT FROM w.new_username
  AND NOT EXISTS (
      SELECT 1 FROM "user" o
      WHERE lower(o.username) = lower(w.new_username)
        AND o.id <> w.user_id
        AND o.id NOT IN (SELECT user_id FROM want)
  );

\echo ''
\echo '=== what will change ==='
SELECT (SELECT count(*) FROM want) AS in_list,
       (SELECT count(*) FROM plan) AS will_rename,
       (SELECT count(*) FROM want) - (SELECT count(*) FROM plan) AS skipped;

\echo ''
\echo '=== does the result stay unique? (both must be 0) ==='
SELECT (SELECT count(*) FROM (SELECT lower(new_username) FROM plan GROUP BY 1 HAVING count(*) > 1) x)
         AS dupes_within_plan,
       (SELECT count(*) FROM plan p JOIN "user" o
          ON lower(o.username) = lower(p.new_username)
         AND o.id <> p.user_id AND o.id NOT IN (SELECT user_id FROM want))
         AS clashes_outside;

\echo ''
\echo '=== sample ==='
SELECT user_id, current_username, new_username FROM plan ORDER BY user_id LIMIT 12;

\if :apply
    \echo ''
    \echo '>>> APPLYING <<<'
    UPDATE "user" u SET username = p.new_username
    FROM plan p WHERE u.id = p.user_id;

    \echo ''
    \echo '=== after ==='
    SELECT count(*) FILTER (WHERE username ~ '^s[0-9]+$') AS still_seeded_form,
           count(*) AS student_logins
    FROM "user" WHERE role = 'student';

    \echo ''
    \echo '=== Afruzbek Abdujjaborov (was s13807) ==='
    SELECT u.id, u.username FROM "user" u
    JOIN gennis_user_link l ON l.management_user_id = u.id
    JOIN gennis_student s ON s.user_id = l.gennis_user_id
    WHERE s.id = 230243;
    COMMIT;
\else
    \echo ''
    \echo '(dry run - nothing written. -v apply=1 to perform it)'
    ROLLBACK;
\endif
